import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Vue Router排障：刷新、404、竞态与提交","description":"区分服务器刷新404、页面路由404、API资源404，以及读取竞态和版本提交失败。","frontmatter":{"title":"Vue Router排障：刷新、404、竞态与提交","description":"区分服务器刷新404、页面路由404、API资源404，以及读取竞态和版本提交失败。","showdocs":{"topics":[{"id":"vue","title":"Vue","link":"/topics/vue/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Vue Router：导航与任务工作台","summary":"区分服务器刷新404、页面路由404、API资源404，以及读取竞态和版本提交失败。","status":"active","related":[{"title":"Nuxt SSR：首屏、注水与请求作用域","link":"/programming/web-plus/vue/plus/subjects/ssr-model","kind":"响应式与组件","scope":"general","audience":"general"},{"title":"Nuxt SSR实践：本地课程目录完整项目","link":"/programming/web-plus/vue/plus/practice/ssr-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"Nuxt SSR实践：本地课程目录完整项目 · Nuxt课程目录的手写契约约定了什么至Nuxt本地API怎样限制输入和响应数据","link":"/programming/web-plus/vue/plus/practice/ssr-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"Nuxt SSR实践：本地课程目录完整项目 · Nuxt课程目录后续怎样安装和验收至练习：扩展公开课程","link":"/programming/web-plus/vue/plus/practice/ssr-application-part-02","kind":"开发实践","scope":"general","audience":"general"},{"title":"Nuxt SSR数据：稳定键、序列化与保密边界","link":"/programming/web-plus/vue/plus/subjects/ssr-data","kind":"响应式与组件","scope":"general","audience":"general"}],"prev":{"text":"Vue Router完整项目：任务列表、详情与编辑","link":"/programming/web-plus/vue/plus/practice/router-application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Vue Router完整项目：任务列表、详情与编辑","link":"/programming/web-plus/vue/plus/practice/router-application"},"next":false},"headers":[],"relativePath":"programming/web-plus/vue/plus/troubleshooting/router-diagnostics.md","filePath":"programming/web-plus/vue/plus/troubleshooting/router-diagnostics.md"}'),s={name:"programming/web-plus/vue/plus/troubleshooting/router-diagnostics.md"};function o(u,e,l,n,p,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="vue-router排障-刷新、404、竞态与提交" tabindex="-1">Vue Router排障：刷新、404、竞态与提交 <a class="header-anchor" href="#vue-router排障-刷新、404、竞态与提交" aria-label="Permalink to &quot;Vue Router排障：刷新、404、竞态与提交&quot;">​</a></h1><p>前置：history模式、开发代理和TaskPage的读取生命周期。按<a href="/programming/web-plus/vue/plus/practice/router-application#project-source">完整任务工作台</a>中的路由表、api.mjs和TaskPage.vue逐层核对。示例未执行；命令与现象均为读者未来自行验证的步骤和预期，不能视为运行记录。</p><h2 id="history-fallback" tabindex="-1">Vue Router详情页刷新404如何处理 <a class="header-anchor" href="#history-fallback" aria-label="Permalink to &quot;Vue Router详情页刷新404如何处理 {#history-fallback}&quot;">​</a></h2><p>Vue Router详情页刷新404如何处理？createWebHistory使用浏览器history API，客户端点击由路由器处理，但刷新/tasks/12时服务器直接收到该路径。静态服务器应正常返回真实资源，把/api交给后端，其余页面路由返回index.html，客户端再判断是否匹配。不能把/api的404也改写成HTML200，否则fetch会在JSON解析时失败并掩盖真实错误。</p><p>本例仅根目录部署；子目录还需同步Vite base、createWebHistory(base)和服务器回退位置。Vite server.proxy只在dev有效，preview和生产需要另设同源反向代理。官方<a href="https://router.vuejs.org/guide/essentials/history-mode.html" target="_blank" rel="noopener noreferrer">HTML5 history模式</a>提供服务器配置思路，读者应在目标服务器验证，不能把模板编译当部署验证。</p><h2 id="route-api-404" tabindex="-1">Vue路由404和任务API404有什么区别 <a class="header-anchor" href="#route-api-404" aria-label="Permalink to &quot;Vue路由404和任务API404有什么区别 {#route-api-404}&quot;">​</a></h2><p>Vue路由404和任务API404有什么区别？页面404表示URL没有匹配到任何前端记录，由兜底NotFound展示；任务404表示URL结构合法但后端没有该任务，由TaskPage显示任务不存在或已删除。格式无效的id由前端先拦截，合法但不存在的id交后端判断。不要把所有情况重定向列表而丢失错误上下文。</p><p>如果看见Unexpected token或HTML，检查开发代理、生产反向代理与history回退是否把API错误替换成页面；检查Content-Type及实际响应体。request在非2xx时保留HTTP状态并给通用解析回退，但成功HTML仍会解析失败，最终页面显示错误。静态契约只表达预期路径，不能证明代理已正确部署。</p><h2 id="stale-page" tabindex="-1">Vue切换地址后仍显示旧任务如何排查 <a class="header-anchor" href="#stale-page" aria-label="Permalink to &quot;Vue切换地址后仍显示旧任务如何排查 {#stale-page}&quot;">​</a></h2><p>Vue切换地址后仍显示旧任务如何排查？先确认读取是否只在mounted执行；复用组件时必须watch具体参数。再检查读取前是否清旧task和草稿、每次请求是否递增generation、成功/失败/finally是否都校验当前序号、onCleanup是否及时注册。只在成功赋值前比较id会遗漏同任务重试与编辑模式变化，序号比单独比较id更完整。</p><p>AbortController只覆盖传入signal的读取；写入完成后也要校验generation再导航。不要用随机延时隐藏竞态，也不要吞掉全部异常使页面永久loading。人工验收要控制慢请求和快速切换顺序，静态阅读只能提供实现依据，本轮没有真实浏览器竞态证据。</p><h2 id="submission-error" tabindex="-1">Vue提交失败后应该重试还是重新加载 <a class="header-anchor" href="#submission-error" aria-label="Permalink to &quot;Vue提交失败后应该重试还是重新加载 {#submission-error}&quot;">​</a></h2><p>Vue提交失败后应该重试还是重新加载？409需要重新加载当前版本再编辑；400先修正输入；404提示任务已删除；网络错误则可能已提交，先核实服务端状态。POST没有幂等键，盲目重试可能重复创建。按钮saving阻止当前视图重复点击，但不能保证跨窗口、刷新或网络层恰好一次。</p><p>重新加载明确丢弃草稿，不在错误发生后悄悄覆盖输入。保存期间离开页面，旧请求仍可能提交，但其完成后的UI动作被generation挡住；返回任务应再次读取。服务端必须执行版本保护，前端按钮禁用只是交互约束。部署、浏览器、可访问性与真实并发验收都留给读者未来独立验证，本轮仅静态检查。</p><h2 id="exercise" tabindex="-1">练习：拆解三种失败 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习：拆解三种失败 {#exercise}&quot;">​</a></h2><p>①直接刷新/tasks/12得到服务器404；②点击/tasks/12得到任务不存在；③API返回HTML200，页面显示JSON解析错误。分别定位到哪一层？有人建议把所有未知路径都回退index.html，这会解决全部问题吗？</p><details class="details custom-block"><summary>参考答案（推演，未执行）</summary><p>①静态服务器缺history回退，需页面路由返回入口。②前端路由已匹配，后端资源不存在，应保留资源404上下文。③常见为/api代理或回退配置错误，把API路径送到SPA入口；先检查响应Content-Type与实际体。所有未知路径无条件回退会掩盖API404和缺失静态资源，不能解决后端资源不存在；应保留/api后端处理和真实静态文件404，只对页面路由回退。</p></details>',17)])])}const m=a(s,[["render",o]]);export{g as __pageData,m as default};
